export const forgeThemes = ['neutral', 'clinical', 'cyber', 'organic', 'premium'] as const;
export const forgeColorModes = ['light', 'dark', 'hc-light', 'hc-dark'] as const;
export const forgeDensities = ['compact', 'comfortable', 'touch'] as const;
export const forgeMotions = ['standard', 'reduced'] as const;

export type ForgeTheme = typeof forgeThemes[number];
export type ForgeColorMode = typeof forgeColorModes[number];
export type ForgeDensity = typeof forgeDensities[number];
export type ForgeMotion = typeof forgeMotions[number];

export const forgeRootAttributes = {
  theme: 'data-forge-theme',
  colorMode: 'data-forge-color-mode',
  density: 'data-forge-density',
  motion: 'data-forge-motion',
} as const;
